// SPDX-License-Identifier: Apache-2.0
// Typed, timestamped events. The append-only log of these is the source of truth for
// runs, handoffs and decisions, and doubles as the audit log (every event has an actor).
import type { AgentConfig, Policy, ProjectConfig, RuleName, TrackerConfig } from './config.ts';
import type {
  Actor,
  Alert,
  Approval,
  Assignment,
  AssignmentPosition,
  AuthStatus,
  BillingInfo,
  BinaryInfo,
  Evidence,
  ExitReason,
  FailureKind,
  Handoff,
  ModelInfo,
  Review,
  Decision,
  Run,
  RunState,
  TestCounts,
  UsageInfo,
  VaultStatus,
  GraphStatus,
  WorkItem,
  TeamMessage,
  DocsStatus,
  OneAnswerStatus,
} from './entities.ts';
import type { BlockedOn, LifecycleState } from './lifecycle.ts';
import type { DesignRevision } from './design.ts';

export interface ControlEventData {
  'design.system_saved':{revision:DesignRevision};
  'team.message_sent': { message: TeamMessage };
  'team.message_acknowledged': { messageId: string; recipientId: string };
  'team.message_notified': { messageId: string; targetRunId: string };
  'decision.created': { decision: Decision };
  'decision.answered': { decisionId: string; answer: string; channel: string };
  'docker.action': { decisionId: string; command: string[]; exitCode: number | null; output: string };
  'daemon.started': { version: string; pid: number };
  'config.loaded': { project: ProjectConfig; tracker: TrackerConfig; policies: Policy };
  'tracker.live_enabled': { type: string; target: string };
  'agent.registered': { config: AgentConfig };
  'agent.removed': Record<string, never>;
  'agent.probed': {
    auth: AuthStatus;
    billing: BillingInfo;
    binary: BinaryInfo | null;
    binaryCandidates: BinaryInfo[];
    models: ModelInfo[];
    newest: string | null;
    usage?: UsageInfo;
  };
  'agent.usage': { usage: UsageInfo };
  'agent.limited': { until: string | null; message: string };
  'agent.unlimited': { reason: string };
  'agent.paused': { reason: string };
  'agent.resumed': Record<string, never>;
  'agent.model_changed': { model: string };
  'agent.queue_set': { now: string | null; next: string[] };
  'work_item.created': { item: WorkItem };
  'work_item.updated': {
    patch: Partial<Pick<WorkItem, 'title' | 'description' | 'acceptance' | 'labels' | 'priority' | 'parentKey' | 'blockedBy' | 'trackerStatus' | 'ownerAgentId' | 'branches' | 'requiresProductionVerification' | 'stage' | 'sprint' | 'workType' | 'origin'>>;
  };
  'work_item.transitioned': { from: LifecycleState; to: LifecycleState; reason: string; blockedOn?: BlockedOn | null };
  'work_item.evidence_added': { evidence: Evidence };
  'work_item.reviewed': { review: Review };
  'work_item.synced': { status: WorkItem['sync']['status']; error?: string | null; key?: string; trackerId?: string; url?: string | null };
  'assignment.created': { assignment: Assignment };
  'assignment.updated': { patch: Partial<Omit<Assignment, 'id' | 'workItemId' | 'createdAt'>> };
  'assignment.positioned': { position: AssignmentPosition };
  'assignment.worktree_ready': { worktree: string; branch: string; baseSha: string };
  'run.created': { run: Run };
  'run.started': { pid: number | null };
  'run.session': { sessionId: string | null; model: string | null };
  'run.state': { state: RunState; reason?: string };
  /** `state` overrides the default (finished / failed / orphaned), e.g. paused. */
  'run.ended': { exit: ExitReason; state?: RunState };
  'run.handoff': { handoff: Handoff };
  'run.usage': { inputTokens: number; outputTokens: number; costUsd?: number };
  'run.files_changed': { files: string[]; outOfScope: string[] };
  'run.tests': { counts: TestCounts; command: string; source: 'agent' | 'daemon' };
  'approval.requested': { approval: Approval };
  'approval.resolved': { approvalId: string; decision: string; by: string; channel: string };
  'alert.raised': { alert: Alert };
  'alert.resolved': { alertId: string; resolution: string };
  'rule.toggled': { rule: RuleName; enabled: boolean };
  'kill_switch.set': { engaged: boolean };
  'context.vault': { status: VaultStatus | null };
  'context.graph': { status: GraphStatus | null };
  'context.docs': { status: DocsStatus | null };
  'context.answer': { status: OneAnswerStatus };
  'context.connected': { vault: string; folders: string[]; semantic: boolean };
}

export interface TranscriptEventData {
  't.message': { role: 'assistant' | 'user' | 'system'; text: string };
  't.reasoning': { text: string };
  't.tool_call': { callId?: string; name: string; summary: string };
  't.tool_result': { callId?: string; ok: boolean; summary: string };
  't.command': { callId?: string; command: string; status: 'started' | 'completed' | 'failed'; exitCode?: number | null; output?: string };
  't.file_edit': { path: string; change: 'add' | 'modify' | 'delete' };
  't.test_result': { counts: TestCounts; command: string };
  't.error': { message: string; failure?: FailureKind };
  't.usage': { inputTokens: number; outputTokens: number };
  't.raw': { stream: 'stdout' | 'stderr'; line: string };
  't.commit': { sha: string; subject: string };
  't.system': { text: string };
}

export type EventDataMap = ControlEventData & TranscriptEventData;
export type ControlEventType = keyof ControlEventData;
export type TranscriptEventType = keyof TranscriptEventData;
export type EventType = keyof EventDataMap;

export interface EventRefs {
  agentId?: string | null;
  runId?: string | null;
  workItemId?: string | null;
  assignmentId?: string | null;
}

export type NewEvent<T extends EventType = EventType> = {
  [K in T]: { type: K; data: EventDataMap[K]; actor?: Actor; ts?: string } & EventRefs;
}[T];

export type EventEnvelope<T extends EventType = EventType> = {
  [K in T]: {
    seq: number;
    id: string;
    ts: string;
    type: K;
    kind: 'control' | 'transcript';
    actor: Actor;
    agentId: string | null;
    runId: string | null;
    workItemId: string | null;
    assignmentId: string | null;
    data: EventDataMap[K];
  };
}[T];

export function isTranscriptType(type: string): type is TranscriptEventType {
  return type.startsWith('t.');
}

export const SYSTEM: Actor = { type: 'system', id: 'control-center' };
export const HUMAN: Actor = { type: 'human', id: 'owner' };
export const agentActor = (id: string): Actor => ({ type: 'agent', id });

/** Summary line used for "last meaningful event"; null for noise (usage, raw, reasoning). */
export function meaningfulSummary(e: { type: string; data: unknown }): string | null {
  const d = e.data as Record<string, unknown>;
  const clip = (s: string, n = 140) => (s.length > n ? s.slice(0, n - 1) + '…' : s);
  switch (e.type) {
    case 't.message':
      return d.role === 'assistant' ? clip(String(d.text).replace(/\s+/g, ' ').trim()) : null;
    case 't.command':
      return d.status === 'started' ? `$ ${clip(String(d.command), 120)}` : `$ ${clip(String(d.command), 100)} → exit ${d.exitCode ?? '?'}`;
    case 't.file_edit':
      return `${d.change === 'add' ? 'created' : d.change === 'delete' ? 'deleted' : 'edited'} ${d.path}`;
    case 't.test_result': {
      const c = d.counts as TestCounts;
      return `tests: ${c.passed} passed, ${c.failed} failed`;
    }
    case 't.error':
      return `error: ${clip(String(d.message))}`;
    case 't.commit':
      return `commit ${String(d.sha).slice(0, 8)} ${clip(String(d.subject), 80)}`;
    case 't.tool_call':
      return `${d.name}: ${clip(String(d.summary), 110)}`;
    default:
      return null;
  }
}

// SPDX-License-Identifier: Apache-2.0
// One lifecycle state machine shared by every view, the daemon and the tracker sync.

export const MAIN_STATES = [
  'backlog',
  'selected',
  'assigned_next',
  'assigned_now',
  'running',
  'handoff_received',
  'in_review',
  'changes_requested',
  'approved',
  'merged',
  'release_candidate',
  'deployed',
  'verified',
] as const;

export const SIDE_STATES = ['blocked', 'stalled', 'failed', 'canceled'] as const;

export type MainState = (typeof MAIN_STATES)[number];
export type SideState = (typeof SIDE_STATES)[number];
export type LifecycleState = MainState | SideState;

export const LIFECYCLE_LABELS: Record<LifecycleState, string> = {
  backlog: 'Backlog',
  selected: 'Selected',
  assigned_next: 'Assigned (Next)',
  assigned_now: 'Assigned (Now)',
  running: 'Running',
  handoff_received: 'Handoff received',
  in_review: 'In review',
  changes_requested: 'Changes requested',
  approved: 'Approved',
  merged: 'Merged to integration',
  release_candidate: 'Release candidate',
  deployed: 'Deployed',
  verified: 'Verified (Done)',
  blocked: 'Blocked',
  stalled: 'Stalled',
  failed: 'Failed',
  canceled: 'Canceled',
};

export type BlockedOn = { kind: 'human' | 'issue' | 'agent'; ref?: string; reason: string };

/** Tracker-neutral status buckets; each tracker adapter maps these to its own names. */
export type TrackerCategory = 'backlog' | 'todo' | 'in_progress' | 'in_review' | 'done' | 'canceled';

export const DEFAULT_TRACKER_CATEGORY: Record<LifecycleState, TrackerCategory> = {
  backlog: 'backlog',
  selected: 'todo',
  assigned_next: 'todo',
  assigned_now: 'todo',
  running: 'in_progress',
  handoff_received: 'in_review',
  in_review: 'in_review',
  changes_requested: 'in_progress',
  approved: 'in_review',
  merged: 'in_review',
  release_candidate: 'in_review',
  deployed: 'in_review',
  verified: 'done',
  blocked: 'in_progress',
  stalled: 'in_progress',
  failed: 'in_progress',
  canceled: 'canceled',
};

const T: Record<LifecycleState, readonly LifecycleState[]> = {
  backlog: ['selected', 'assigned_next', 'assigned_now', 'canceled', 'blocked'],
  selected: ['backlog', 'assigned_next', 'assigned_now', 'canceled', 'blocked'],
  assigned_next: ['assigned_now', 'selected', 'backlog', 'canceled', 'blocked'],
  assigned_now: ['running', 'assigned_next', 'selected', 'canceled', 'blocked', 'failed'],
  running: ['handoff_received', 'stalled', 'failed', 'blocked', 'canceled', 'assigned_now'],
  stalled: ['running', 'failed', 'canceled', 'assigned_now', 'blocked', 'handoff_received'],
  failed: ['assigned_now', 'assigned_next', 'running', 'selected', 'canceled', 'blocked'],
  handoff_received: ['in_review', 'running', 'assigned_now', 'changes_requested', 'blocked', 'canceled'],
  in_review: ['changes_requested', 'approved', 'blocked', 'canceled'],
  changes_requested: ['assigned_now', 'assigned_next', 'running', 'blocked', 'canceled'],
  approved: ['merged', 'changes_requested', 'blocked', 'canceled'],
  merged: ['release_candidate', 'verified', 'blocked'],
  release_candidate: ['deployed', 'blocked', 'merged'],
  deployed: ['verified', 'blocked', 'release_candidate'],
  verified: [],
  // Blocked resumes to wherever the work actually is; validated against `resumeTo` by callers.
  blocked: ['backlog', 'selected', 'assigned_next', 'assigned_now', 'running', 'handoff_received', 'in_review', 'changes_requested', 'approved', 'merged', 'release_candidate', 'deployed', 'canceled'],
  canceled: ['backlog'],
};

export interface EvidenceLike {
  kind: string;
  verified: boolean;
  env?: string;
}

export interface TransitionContext {
  evidence?: readonly EvidenceLike[];
  /** Acceptance needs production or real-device verification before Done. */
  requiresProductionVerification?: boolean;
}

export type TransitionCheck = { ok: true } | { ok: false; reason: string };

export function allowedTransitions(from: LifecycleState): readonly LifecycleState[] {
  return T[from];
}

export function canTransition(from: LifecycleState, to: LifecycleState, ctx: TransitionContext = {}): TransitionCheck {
  if (from === to) return { ok: false, reason: `already ${from}` };
  if (!T[from].includes(to)) return { ok: false, reason: `${LIFECYCLE_LABELS[from]} → ${LIFECYCLE_LABELS[to]} is not a valid transition` };
  if (to === 'verified') {
    const ev = ctx.evidence ?? [];
    const merge = ev.some((e) => e.kind === 'merge' && e.verified);
    const acceptance = ev.filter((e) => e.kind === 'acceptance' && e.verified);
    if (!merge) return { ok: false, reason: 'Done requires verified merge evidence' };
    if (acceptance.length === 0) return { ok: false, reason: 'Done requires verified acceptance evidence' };
    if (ctx.requiresProductionVerification && !acceptance.some((e) => e.env === 'production' || e.env === 'device')) {
      return { ok: false, reason: 'Acceptance needs production or real-device evidence before Done' };
    }
  }
  return { ok: true };
}

/**
 * Shortest valid path from → to (excluding `from`), stepping only through ordinary forward
 * states, e.g. backlog → running = [assigned_now, running]. Null if unreachable.
 */
export function transitionPath(from: LifecycleState, to: LifecycleState): LifecycleState[] | null {
  if (from === to) return [];
  const via = new Set<LifecycleState>(['selected', 'assigned_next', 'assigned_now', 'running', 'handoff_received', 'in_review', 'approved', 'merged', 'release_candidate', 'deployed']);
  const prev = new Map<LifecycleState, LifecycleState>();
  const queue: LifecycleState[] = [from];
  const seen = new Set<LifecycleState>([from]);
  while (queue.length) {
    const cur = queue.shift()!;
    for (const n of T[cur]) {
      if (seen.has(n)) continue;
      seen.add(n);
      prev.set(n, cur);
      if (n === to) {
        const path: LifecycleState[] = [n];
        for (let p = prev.get(n)!; p !== from; p = prev.get(p)!) path.unshift(p);
        return path;
      }
      if (via.has(n)) queue.push(n);
    }
  }
  return null;
}

export function isTerminal(s: LifecycleState): boolean {
  return s === 'verified' || s === 'canceled';
}

export function isActiveWork(s: LifecycleState): boolean {
  return s === 'running' || s === 'stalled';
}

/** Board column grouping used by the Work Board and the pipeline strip. */
export const PIPELINE: { id: string; label: string; states: LifecycleState[] }[] = [
  { id: 'backlog', label: 'Backlog', states: ['backlog'] },
  { id: 'ready', label: 'Ready', states: ['selected'] },
  { id: 'assigned', label: 'Assigned', states: ['assigned_next', 'assigned_now'] },
  { id: 'running', label: 'Running', states: ['running'] },
  { id: 'handoff', label: 'Handoff', states: ['handoff_received'] },
  { id: 'review', label: 'Review', states: ['in_review', 'changes_requested', 'approved'] },
  { id: 'merged', label: 'Merged', states: ['merged', 'release_candidate', 'deployed'] },
  { id: 'done', label: 'Done', states: ['verified'] },
  { id: 'attention', label: 'Needs attention', states: ['blocked', 'stalled', 'failed'] },
];

// SPDX-License-Identifier: Apache-2.0
// Model inventory helpers: newest-model selection, model classes and quality floors.
// Vendors name models inconsistently, so everything here is pattern-based and overridable
// from policy config. Unknown models are reported as unknown, never guessed into a class.
import { EFFORTS, type Effort } from './config.ts';
import type { ModelInfo } from './entities.ts';

const NUMERIC = /^\d{1,3}(?:\.\d{1,3})*$/;
const PREFIXED = /^[a-z]{1,2}(\d{1,3}(?:\.\d{1,3})*)$/; // o3, v2
const DATE = /^\d{8}$/;

export interface ParsedModel {
  id: string;
  version: number[];
  date: number;
  effort: Effort | null;
  fast: boolean;
  /** id with effort / speed suffixes removed, e.g. gpt-5.3-codex-high-fast → gpt-5.3-codex */
  base: string;
}

export function parseModelId(id: string): ParsedModel {
  const tokens = id.toLowerCase().split(/[-_/\s]+/).filter(Boolean);
  const version: number[] = [];
  let date = 0;
  let started = false;
  let done = false;
  for (const t of tokens) {
    if (DATE.test(t)) {
      date = Number(t);
      continue;
    }
    const n = NUMERIC.test(t) ? t : PREFIXED.exec(t)?.[1];
    if (n && !done) {
      version.push(...n.split('.').map(Number));
      started = true;
    } else if (started) done = true;
  }
  let rest = [...tokens];
  let fast = false;
  let effort: Effort | null = null;
  while (rest.length > 1) {
    const last = rest[rest.length - 1];
    if (last === 'fast') {
      fast = true;
      rest = rest.slice(0, -1);
    } else if ((EFFORTS as readonly string[]).includes(last)) {
      effort = effort ?? (last as Effort);
      rest = rest.slice(0, -1);
    } else if (last === 'thinking' || DATE.test(last)) {
      rest = rest.slice(0, -1);
    } else break;
  }
  return { id, version, date, effort, fast, base: rest.join('-') };
}

export function compareVersions(a: number[], b: number[]): number {
  for (let i = 0; i < Math.max(a.length, b.length); i++) {
    const d = (a[i] ?? 0) - (b[i] ?? 0);
    if (d !== 0) return d;
  }
  return 0;
}

export function globToRegExp(pattern: string): RegExp {
  const esc = pattern.replace(/[.+^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*').replace(/\?/g, '.');
  return new RegExp(`^${esc}$`, 'i');
}

export function matchesAny(id: string, patterns: readonly string[] | undefined): boolean {
  if (!patterns || patterns.length === 0) return false;
  return patterns.some((p) => globToRegExp(p).test(id));
}

export function matchesFamily(id: string, family: string | undefined): boolean {
  if (!family) return true;
  const f = family.toLowerCase();
  const lid = id.toLowerCase();
  if (f.includes('*')) return globToRegExp(f).test(lid);
  return lid === f || lid.startsWith(f + '-') || lid.startsWith(f + '.') || lid.startsWith(f) || lid.includes(`-${f}-`) || lid.endsWith(`-${f}`);
}

export const effortRank = (e: Effort | null | undefined): number => (e ? EFFORTS.indexOf(e) : -1);

export interface PickOptions {
  family?: string;
  effort?: Effort | null;
  allowed?: readonly string[];
  denied?: readonly string[];
  /** "Fast" variants spend more included usage; excluded unless asked for. */
  allowFast?: boolean;
}

export function eligibleModels(models: readonly ModelInfo[], o: PickOptions = {}): ModelInfo[] {
  return models.filter(
    (m) =>
      !m.hidden &&
      m.id !== 'auto' &&
      matchesFamily(m.id, o.family) &&
      (!o.allowed || o.allowed.length === 0 || matchesAny(m.id, o.allowed)) &&
      !matchesAny(m.id, o.denied) &&
      (o.allowFast || !parseModelId(m.id).fast),
  );
}

/** Newest eligible model: highest version, then vendor priority, then closest effort match. */
export function pickNewest(models: readonly ModelInfo[], o: PickOptions = {}): ModelInfo | null {
  const cands = eligibleModels(models, o);
  if (cands.length === 0) return null;
  const want = effortRank(o.effort ?? null);
  const scored = cands.map((m) => ({ m, p: parseModelId(m.id) }));
  scored.sort((a, b) => {
    const v = compareVersions(b.p.version, a.p.version);
    if (v !== 0) return v;
    if (b.p.date !== a.p.date) return b.p.date - a.p.date;
    const pa = a.m.priority ?? Number.MAX_SAFE_INTEGER;
    const pb = b.m.priority ?? Number.MAX_SAFE_INTEGER;
    if (pa !== pb) return pa - pb;
    if (want >= 0) {
      const da = a.p.effort ? Math.abs(effortRank(a.p.effort) - want) + (effortRank(a.p.effort) < want ? 0.5 : 0) : 10;
      const db = b.p.effort ? Math.abs(effortRank(b.p.effort) - want) + (effortRank(b.p.effort) < want ? 0.5 : 0) : 10;
      if (da !== db) return da - db;
    }
    return a.m.id.localeCompare(b.m.id);
  });
  return scored[0].m;
}

/** True when `model` is (one of) the newest eligible models: same version line as the pick. */
export function isNewest(model: string, models: readonly ModelInfo[], o: PickOptions = {}): { newest: boolean; best: string | null } {
  const best = pickNewest(models, o);
  if (!best) return { newest: true, best: null };
  if (!models.some((m) => m.id === model)) return { newest: false, best: best.id };
  const a = parseModelId(model);
  const b = parseModelId(best.id);
  return { newest: compareVersions(a.version, b.version) >= 0 && (b.date === 0 || a.date >= b.date), best: best.id };
}

// ---- classes & quality floors -------------------------------------------------------------

export const CLASS_RANK: Record<string, number> = {
  lite: 0,
  standard: 1,
  'sonnet-class': 2,
  'pro-class': 2,
  strong: 2,
  'opus-class': 3,
  frontier: 3,
};

export const DEFAULT_MODEL_CLASSES: { class: string; pattern: string }[] = [
  { class: 'lite', pattern: '(^|[-_.])(lite|mini|nano|haiku)([-_.]|$)' },
  { class: 'standard', pattern: 'flash' },
  { class: 'opus-class', pattern: '(^|[-_.])(opus|fable|astra)([-_.]|$)|^gpt-6|deep-?research|(^|-)pro(-|$)' },
  { class: 'sonnet-class', pattern: '(^|[-_.])(sonnet|codex|composer|grok|gemini|sol|terra|luna)([-_.]|$)|^gpt-5|^o[34]' },
];

export function modelClass(model: string, classes = DEFAULT_MODEL_CLASSES): string | null {
  const id = model.toLowerCase();
  for (const c of classes) if (new RegExp(c.pattern, 'i').test(id)) return c.class;
  return null;
}

export function parseFloor(floor: string): { cls: string | null; effort: Effort | null } {
  const parts = floor.trim().toLowerCase().split(/\s+/);
  const effort = (parts.find((p) => (EFFORTS as readonly string[]).includes(p)) as Effort | undefined) ?? null;
  const cls = parts.find((p) => p in CLASS_RANK) ?? null;
  return { cls, effort };
}

export interface FloorCheck {
  status: 'pass' | 'warn' | 'fail';
  message: string;
}

export function checkQualityFloor(model: string, effort: Effort | null, floor: string | undefined, classes = DEFAULT_MODEL_CLASSES): FloorCheck {
  if (!floor) return { status: 'pass', message: 'no quality floor for this work' };
  const f = parseFloor(floor);
  const cls = modelClass(model, classes);
  const eff = parseModelId(model).effort ?? effort;
  if (f.cls) {
    if (!cls) return { status: 'warn', message: `can't classify ${model}; floor is ${floor} (add a model_classes pattern)` };
    if (CLASS_RANK[cls] < CLASS_RANK[f.cls]) return { status: 'fail', message: `${model} is ${cls}, below the ${floor} floor` };
  }
  if (f.effort) {
    if (!eff) return { status: 'warn', message: `effort unknown; floor needs ${f.effort}` };
    if (effortRank(eff) < effortRank(f.effort)) return { status: 'fail', message: `effort ${eff} is below the ${floor} floor` };
  }
  return { status: 'pass', message: `${model}${eff ? ` @ ${eff}` : ''} meets ${floor}` };
}

/** Category of a work item for quality floors: first configured category whose labels match. */
export function workCategory(labels: readonly string[], categories: Record<string, string[]>): string {
  const lower = labels.map((l) => l.toLowerCase());
  for (const [cat, ls] of Object.entries(categories)) if (ls.some((l) => lower.includes(l.toLowerCase()))) return cat;
  return 'code';
}

// SPDX-License-Identifier: Apache-2.0
// Subscription agents on one vendor login share limits. Capacity is never multiplied by cloning.
import type { AgentConfig } from './config.ts';
import type { AgentState } from './entities.ts';

export function subscriptionGroup(config:AgentConfig):string|null {
  if(config.provider!=='subscription') return null;
  const official=({'claude-headless':'anthropic','codex-cli':'openai','cursor-agent-cli':'cursor'} as Record<string,string>)[config.adapter];
  // These adapters use the same native login. A renamed group is not a different account.
  if(official) return official;
  return config.subscription_group ?? config.vendor?.toLowerCase() ?? `${config.adapter}:${config.command ?? ''}`;
}

export function subscriptionPeers(agents:Record<string,AgentState>,id:string):AgentState[] {
  const a=agents[id];if(!a)return [];
  const group=subscriptionGroup(a.config);
  return group===null?[a]:Object.values(agents).filter(p=>subscriptionGroup(p.config)===group);
}

export function sharedCapacity(agents:Record<string,AgentState>,id:string) {
  const peers=subscriptionPeers(agents,id),own=agents[id];
  if(!own) throw new Error(`unknown agent ${id}`);
  const reported=peers.filter(a=>a.usage.windows.some(w=>typeof w.usedPercent==='number') || a.usage.status==='limited').sort((a,b)=>Date.parse(b.usage.checkedAt)-Date.parse(a.usage.checkedAt));
  const limited=peers.find(a=>a.limitedUntil);
  return {group:subscriptionGroup(own.config),peerIds:peers.map(a=>a.id),usage:reported[0]?.usage ?? own.usage,limitedUntil:limited?.limitedUntil ?? null};
}

// SPDX-License-Identifier: Apache-2.0
// Dispatch pre-flight. Pure: the daemon gathers the facts, this decides.
import type { Policy, ProjectConfig } from './config.ts';
import type { AgentState, Assignment, PreflightCheck, PreflightResult, WorkItem } from './entities.ts';
import { checkQualityFloor, isNewest, matchesAny, pickNewest, workCategory, type PickOptions } from './models.ts';
import { scopesOverlap } from './pathScope.ts';
import { containsSecret } from './redact.ts';

export const COORDINATION_LABELS = ['coordination', 'planning', 'triage', 'research'];

export interface PreflightInput {
  now: string;
  item: WorkItem | undefined;
  assignment: Assignment;
  agent: AgentState | undefined;
  project: ProjectConfig;
  policies: Policy;
  killSwitch: boolean;
  /** Other assignments that currently hold a worktree (position now, not done). */
  activeAssignments: Assignment[];
  /** Daemon's check that the pinned vendor binary is still the one that was probed. */
  binaryCheck?: { status: 'pass' | 'warn' | 'fail'; message: string };
  denylist?: readonly string[];
  /** Spend recorded today for this agent (metered providers). */
  spentTodayUsd?: number;
  /** Whether the provider's API key / local server is available. */
  providerCheck?: { status: 'pass' | 'warn' | 'fail'; message: string };
}

export function pickOptions(agent: AgentState, policies: Policy): PickOptions {
  return {
    family: agent.config.model_family,
    effort: agent.config.effort ?? null,
    allowed: agent.config.allowed_models ?? policies.allowed_models,
    denied: policies.denied_models,
  };
}

/** The model a dispatch would use right now. */
export function resolveModel(agent: AgentState, policies: Policy): { model: string | null; newest: string | null } {
  const opts = pickOptions(agent, policies);
  const newest = pickNewest(agent.models.available, opts)?.id ?? null;
  if (agent.config.model !== 'newest') return { model: agent.config.model, newest };
  return { model: newest ?? agent.config.model_family ?? null, newest };
}

export function runPreflight(i: PreflightInput): PreflightResult {
  const checks: PreflightCheck[] = [];
  const add = (c: PreflightCheck) => checks.push(c);
  const { item, agent, assignment, policies } = i;
  const relay = agent?.config.adapter === 'relay';

  add(i.killSwitch ? { id: 'kill_switch', label: 'Kill switch', status: 'fail', message: 'kill switch is engaged; release it to dispatch' } : { id: 'kill_switch', label: 'Kill switch', status: 'pass', message: 'not engaged' });

  if (!item) add({ id: 'issue', label: 'Issue exists', status: 'fail', message: 'no work item: no issue, no dispatch' });
  else if (!item.key || !item.trackerId) {
    add({ id: 'issue', label: 'Issue exists', status: 'fail', message: item.sync.status === 'dry_run' ? 'tracker is not live yet; issue not created in the tracker' : 'issue is not confirmed in the tracker yet' });
  } else if (item.state === 'verified' || item.state === 'canceled') {
    add({ id: 'issue', label: 'Issue exists', status: 'fail', message: `${item.key} is ${item.state}` });
  } else add({ id: 'issue', label: 'Issue exists', status: 'pass', message: `${item.key} is in the tracker` });

  if (!agent) {
    add({ id: 'agent', label: 'Agent', status: 'fail', message: `unknown agent ${assignment.agentId}` });
    return finish(checks, null, i.now);
  }

  if (agent.config.mode === 'coordinator-only') {
    const coordination = item?.labels.some((l) => COORDINATION_LABELS.includes(l.toLowerCase())) ?? false;
    add(coordination ? { id: 'coordinator', label: 'Coordinator-only', status: 'pass', message: 'coordination work' } : { id: 'coordinator', label: 'Coordinator-only', status: 'fail', message: `${agent.config.name} is coordinator-only; give code work to an engineer to save its usage` });
  }
  if(agent.config.enabled === false) add({id:'enabled',label:'Agent enabled',status:'fail',message:'This agent is a saved draft. Enable it in the agent builder before dispatch.'});

  let model: string | null = null;
  if (relay) {
    add({ id: 'relay', label: 'Relay agent', status: 'pass', message: 'the human pastes the prompt; auth, billing and model are checked in the vendor app' });
  } else {
    add(
      agent.auth.state === 'logged_in'
        ? { id: 'auth', label: 'Signed in', status: 'pass', message: agent.auth.detail ?? 'logged in' }
        : agent.auth.state === 'unknown'
          ? { id: 'auth', label: 'Signed in', status: 'warn', message: 'login state unknown; re-probe the agent', fix: { kind: 'reprobe' } }
          : { id: 'auth', label: 'Signed in', status: 'fail', message: `${agent.auth.state.replace('_', ' ')}${agent.auth.fix ? `: ${agent.auth.fix}` : ''}` },
    );

    const b = agent.billing;
    if (agent.config.billing === 'local' || b.mode === 'local') add({ id: 'billing', label: 'Billing', status: 'pass', message: `local model (${agent.config.provider}): runs on this machine, no cost` });
    else if (agent.config.metered_opt_in) {
      const cap = agent.config.budget_usd_per_day;
      const spent = i.spentTodayUsd ?? 0;
      add({ id: 'billing', label: 'Billing', status: 'warn', message: `metered (${agent.config.provider}), opted in: this run costs money${cap ? `; $${spent.toFixed(2)} of $${cap.toFixed(2)} spent today` : '; no daily cap set'}` });
      if (cap !== undefined && spent >= cap) add({ id: 'budget', label: 'Daily budget', status: 'fail', message: `$${spent.toFixed(2)} spent today reaches the $${cap.toFixed(2)} cap for ${agent.config.name}` });
    }
    else if (b.mode === 'metered') add({ id: 'billing', label: 'Billing', status: 'fail', message: `detected metered billing (${b.source}); zero extra spend blocks dispatch` });
    else if (b.mode === 'subscription') add({ id: 'billing', label: 'Billing', status: b.overage === 'on' ? 'fail' : 'pass', message: b.overage === 'on' ? 'paid overage is on; turn it off or opt in' : `included subscription usage (${b.source})${b.overage === 'unknown' ? '; overage state unknown, verify it is off' : ''}` });
    else add({ id: 'billing', label: 'Billing', status: 'fail', message: 'billing mode is unknown; dispatch requires a confirmed subscription or explicit per-agent paid opt-in' });

    if (agent.limitedUntil || agent.usage.status==='limited' || agent.usage.windows.some(w=>w.usedPercent!==null && w.usedPercent>=100)) add({ id: 'usage', label: 'Usage', status: 'fail', message: `usage limit reached${agent.limitedUntil && agent.limitedUntil !== 'unknown' ? ` until ${agent.limitedUntil}` : ''}` });
    else add({ id: 'usage', label: 'Usage', status: agent.usage.status === 'near_limit' ? 'warn' : 'pass', message: agent.usage.status === 'unknown' ? 'included usage not exposed by vendor' : `usage ${agent.usage.status}` });

    const resolved = assignment.model ? { model: assignment.model, newest: resolveModel(agent, policies).newest } : resolveModel(agent, policies);
    model = resolved.model;
    const opts = pickOptions(agent, policies);
    if (!model) add({ id: 'model', label: 'Model', status: 'fail', message: 'no eligible model found; re-probe or set model in config', fix: { kind: 'reprobe' } });
    else {
      const denied = matchesAny(model, policies.denied_models);
      const allowList = agent.config.allowed_models ?? policies.allowed_models;
      const notAllowed = allowList && allowList.length > 0 && !matchesAny(model, allowList);
      if (denied || notAllowed) add({ id: 'model', label: 'Model allowed', status: 'fail', message: `${model} is ${denied ? 'denied by policy' : 'not in the allowed list'}` });
      else add({ id: 'model', label: 'Model allowed', status: 'pass', message: model });

      if (agent.models.available.length === 0) {
        add({ id: 'newest', label: 'Newest model', status: 'warn', message: 'no model inventory; re-probe to verify', fix: { kind: 'reprobe' } });
      } else {
        const n = isNewest(model, agent.models.available, opts);
        if (n.newest) add({ id: 'newest', label: 'Newest model', status: 'pass', message: `${model} is the newest eligible model` });
        else add({ id: 'newest', label: 'Newest model', status: policies.newest_model_rule ? 'fail' : 'warn', message: `${n.best} is newer than ${model}`, fix: n.best ? { kind: 'use_model', model: n.best } : undefined });
      }

      const cat = workCategory(item?.labels ?? [], i.project.categories);
      const floor = policies.quality_floor[cat];
      const q = checkQualityFloor(model, assignment.effort ?? agent.config.effort ?? null, floor, policies.model_classes ?? undefined);
      add({ id: 'quality', label: `Quality floor (${cat})`, status: q.status, message: q.message });
    }
    if (i.binaryCheck) add({ id: 'binary', label: 'Pinned binary', ...i.binaryCheck });
    if (i.providerCheck) add({ id: 'provider', label: `Provider (${agent.config.provider})`, ...i.providerCheck });
  }

  const overlaps = i.activeAssignments.filter((o) => o.id !== assignment.id && scopesOverlap(o.allowedPaths, assignment.allowedPaths));
  add(
    overlaps.length === 0
      ? { id: 'paths', label: 'Path overlap', status: 'pass', message: 'no overlap with active assignments' }
      : { id: 'paths', label: 'Path overlap', status: 'fail', message: `overlaps ${overlaps.map((o) => `${o.agentId}:${o.allowedPaths.join(',') || '(whole repo)'}`).join('; ')}; narrow allowed paths or queue it` },
  );

  const secrets = containsSecret(assignment.prompt, { denylist: i.denylist });
  add(secrets.length === 0 ? { id: 'secrets', label: 'No secrets in prompt', status: 'pass', message: 'clean' } : { id: 'secrets', label: 'No secrets in prompt', status: 'fail', message: `prompt contains ${secrets.join(', ')}` });

  return finish(checks, model, i.now);
}

function finish(checks: PreflightCheck[], model: string | null, at: string): PreflightResult {
  return { ok: checks.every((c) => c.status !== 'fail'), checks, model, at };
}

