// SPDX-License-Identifier: Apache-2.0
import { execFileSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseConfig, type ControlCenterConfig } from '@acc/core';
import { Daemon, type DaemonOptions } from '../src/daemon.ts';
import { createServer } from '../src/server/http.ts';

export const ROOT = fileURLToPath(new URL('../../../', import.meta.url));
export const FAKE_BIN = path.join(ROOT, 'examples', 'fake-agent', 'bin');

export function tmpDir(prefix: string): string {
  return fs.mkdtempSync(path.join(os.tmpdir(), `acc-${prefix}-`));
}

export function git(cwd: string, ...args: string[]): string {
  return execFileSync('git', args, { cwd, encoding: 'utf8', env: { ...process.env, GIT_AUTHOR_NAME: 't', GIT_AUTHOR_EMAIL: 't@example.com', GIT_COMMITTER_NAME: 't', GIT_COMMITTER_EMAIL: 't@example.com' } }).trim();
}

/** A fresh git repo seeded from examples/sample-repo with main + integration branches. */
export function makeRepo(): string {
  const dir = tmpDir('repo');
  fs.cpSync(path.join(ROOT, 'examples', 'sample-repo'), dir, { recursive: true });
  git(dir, 'init', '-q', '-b', 'main');
  git(dir, 'add', '-A');
  git(dir, 'commit', '-q', '-m', 'initial');
  git(dir, 'branch', 'integration');
  return dir;
}

export function makeConfig(repo: string, over: Record<string, unknown> = {}): ControlCenterConfig {
  return parseConfig({
    project: { name: 'sample', repo, integration_branch: 'integration', protected_branches: ['main'], checks: { test: 'node --test' } },
    tracker: { type: 'local' },
    policies: { stall: { no_event_minutes: 10, approval_pending_minutes: 15 }, quality_floor: {} },
    graphify:{enabled:false},
    agents: [
      { id: 'claude', name: 'Claude Code', role: 'engineer', adapter: 'claude-headless', binary: path.join(FAKE_BIN, 'claude'), model: 'newest', model_family: 'opus', effort: 'high' },
      { id: 'codex', name: 'Codex', role: 'engineer', adapter: 'codex-cli', binary: path.join(FAKE_BIN, 'codex'), model: 'newest', effort: 'high' },
      { id: 'cursor', name: 'Cursor', role: 'engineer', adapter: 'cursor-agent-cli', binary: path.join(FAKE_BIN, 'cursor-agent'), model: 'newest', model_family: 'claude-opus', effort: 'high' },
      { id: 'ag', name: 'Antigravity', role: 'engineer', adapter: 'relay' },
    ],
    ...over,
  });
}

export interface Harness {
  d: Daemon;
  url: string;
  dataDir: string;
  close(): Promise<void>;
}

export async function startDaemon(config: ControlCenterConfig, o: Partial<DaemonOptions> & { dataDir?: string; server?: boolean } = {}): Promise<Harness> {
  const dataDir = o.dataDir ?? tmpDir('data');
  const d = new Daemon({ config, dataDir, allowTempDataDir: true, rulesTickMs: 3_600_000, outboxTickMs: 100, supervisorPollMs: 50, ...o });
  d.rules.retryDelayMs = 0;
  d.rules.connectivity = async () => true;
  let close = async () => {};
  let url = '';
  if (o.server !== false) {
    const srv = await createServer(d, { port: 0 });
    url = srv.url;
    close = async () => {
      await srv.app.close();
    };
  }
  await d.start();
  await d.context.answer.refresh(false);
  return {
    d,
    url,
    dataDir,
    async close() {
      await d.setKillSwitch(true).catch(() => undefined);
      await close();
      await d.shutdown();
    },
  };
}

export async function waitFor<T>(fn: () => T | null | undefined | false, ms = 20_000, label = 'condition'): Promise<T> {
  const end = Date.now() + ms;
  for (;;) {
    const v = fn();
    if (v) return v;
    if (Date.now() > end) throw new Error(`timed out waiting for ${label}`);
    await new Promise((r) => setTimeout(r, 50));
  }
}

// SPDX-License-Identifier: Apache-2.0
import { HUMAN, newId, type Decision } from '@acc/core';
import { run, type ExecResult } from './exec.ts';
import type { Daemon } from './daemon.ts';
type DockerRun = (args: string[]) => Promise<ExecResult>;
export class ProjectDocker {
  readonly d: Daemon;
  readonly execute: DockerRun;
  constructor(d: Daemon, execute?: DockerRun) { this.d = d; this.execute = execute ?? (args => run('docker', args, { timeoutMs: 30000, maxBytes: 128000 })); }
  async list() {
    const project = this.d.config.project.docker_project ?? this.d.config.project.name;
    const r = await this.execute(['ps', '-a', '--filter', `label=com.docker.compose.project=${project}`, '--format', '{{json .}}']);
    if (r.code !== 0) return { available: false, project, containers: [], error: r.error ?? r.stderr.trim() };
    const containers = r.stdout.split('\n').filter(Boolean).map(line => JSON.parse(line) as { ID: string; Names: string; State: string; Status: string; Image: string });
    return { available: true, project, containers, error: null };
  }
  private async target(id: string) {
    if (!/^[a-f0-9]{12,64}$/.test(id)) throw new Error('Invalid container ID');
    const { containers } = await this.list();
    if (!containers.some(c => c.ID === id)) throw new Error('Container is outside this configured Compose project');
    return id;
  }
  async logs(id: string) {
    await this.target(id);
    const r = await this.execute(['logs', '--timestamps', '--tail', '300', id]);
    return { text: this.d.redactText(r.stdout + r.stderr), exitCode: r.code };
  }
  async request(id: string, action: string) {
    await this.target(id);
    if (!['start', 'stop', 'restart'].includes(action)) throw new Error('Unsupported Docker action');
    const decision: Decision = { id: newId('decision'), question: `Run docker ${action} ${id} in ${this.d.config.project.docker_project ?? this.d.config.project.name}?`, options: ['approve', 'deny'], recommendation: null, evidenceLinks: [], urgency: 'normal', irreversible: false, answer: null, answeredAt: null, channel: null, createdAt: this.d.nowIso() };
    this.d.commit([{ type: 'decision.created', actor: HUMAN, data: { decision } }], [], () => this.d.store.kvSet(`docker:${decision.id}`, JSON.stringify({ id, action, expires: Date.now() + 120000, consumed: false })));
    return { decision };
  }
  async resolve(decisionId: string, answer: string) {
    const raw = this.d.store.kvGet(`docker:${decisionId}`);
    const decision = this.d.state.decisions[decisionId];
    if (!raw || !decision || decision.answeredAt) throw new Error('Approval missing or already consumed');
    const a = JSON.parse(raw) as { id: string; action: string; expires: number; consumed: boolean };
    if (a.consumed || a.expires < Date.now()) throw new Error('Approval expired or consumed');
    if (!['approve', 'deny'].includes(answer)) throw new Error('Choose approve or deny');
    await this.target(a.id);
    // Re-check after await: simultaneous confirmations cannot execute the same approval twice.
    if (this.d.state.decisions[decisionId].answeredAt) throw new Error('Approval already consumed');
    this.d.commit([{ type: 'decision.answered', actor: HUMAN, data: { decisionId, answer, channel: 'dashboard' } }], [], () => this.d.store.kvSet(`docker:${decisionId}`, JSON.stringify({ ...a, consumed: true })));
    if (answer === 'deny') return { executed: false };
    const r = await this.execute([a.action, a.id]);
    this.d.commit([{ type: 'docker.action', actor: HUMAN, data: { decisionId, command: ['docker', a.action, a.id], exitCode: r.code, output: this.d.redactText(r.stdout + r.stderr + (r.error ?? '')) } }]);
    return { executed: true, exitCode: r.code, output: this.d.redactText(r.stdout + r.stderr) };
  }
}

// SPDX-License-Identifier: Apache-2.0
// Tracker sync. Writes come from the transactional outbox (committed together with the lifecycle
// event that caused them) and are delivered in order per issue with retries; failures are loud.
// The poller ingests changes made directly in the tracker.
import type { LifecycleState, NewEvent, TrackerCategory, WorkItem } from '@acc/core';
import { DEFAULT_TRACKER_CATEGORY, newId } from '@acc/core';
import { TrackerNotLiveError, type TrackerIssue } from './adapters/trackers/types.ts';
import type { Daemon } from './daemon.ts';
import type { OutboxRow } from './store/eventStore.ts';

export class OutboxWorker {
  readonly d: Daemon;
  private timer: NodeJS.Timeout | null = null;
  private running = false;
  private again = false;

  constructor(d: Daemon) {
    this.d = d;
  }

  start(ms: number): void {
    if (!this.timer) this.timer = setInterval(() => void this.drain(), ms);
    void this.drain();
  }

  stop(): void {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  kick(): void {
    void this.drain();
  }

  async drain(): Promise<void> {
    if (this.running) {
      this.again = true;
      return;
    }
    this.running = true;
    try {
      do {
        this.again = false;
        const rows = this.d.store.pendingOutbox(this.d.nowIso());
        const blocked = new Set<string>();
        for (const row of rows) {
          if (blocked.has(row.workItemId) || this.d.store.undeliveredBefore(row.workItemId, row.id)) {
            blocked.add(row.workItemId);
            continue;
          }
          const ok = await this.deliver(row);
          if (!ok) blocked.add(row.workItemId);
        }
      } while (this.again);
    } finally {
      this.running = false;
    }
  }

  private async deliver(row: OutboxRow): Promise<boolean> {
    const d = this.d;
    const t = d.tracker;
    const item = d.state.workItems[row.workItemId];
    if (!item) {
      d.store.markDelivered(row.id);
      return true;
    }
    try {
      if (row.op === 'create_issue') {
        const p = row.payload as { title: string; description: string; acceptance: string[]; labels: string[]; priority?: number };
        const issue = await t.createIssue(p);
        d.commit([{ type: 'work_item.synced', workItemId: item.id, data: { status: 'synced', key: issue.key, trackerId: issue.id, url: issue.url } }, { type: 'work_item.updated', workItemId: item.id, data: { patch: { trackerStatus: issue.status } } }]);
      } else {
        if (!item.trackerId) throw new Error('issue not created in the tracker yet');
        if (row.op === 'set_status') {
          const p = row.payload as { category: TrackerCategory; lifecycle: LifecycleState };
          await t.setStatus(item.trackerId, p.category, p.lifecycle);
          d.commit([{ type: 'work_item.synced', workItemId: item.id, data: { status: 'synced' } }, { type: 'work_item.updated', workItemId: item.id, data: { patch: { trackerStatus: { category: p.category, native: p.category } } } }]);
        } else if (row.op === 'comment') {
          await t.comment(item.trackerId, String((row.payload as { body: string }).body));
          d.commit([{ type: 'work_item.synced', workItemId: item.id, data: { status: 'synced' } }]);
        }
      }
      d.store.markDelivered(row.id);
      d.resolveAlerts((a) => a.dedupeKey === `sync:${item.id}`, 'delivered');
      return true;
    } catch (e) {
      const notLive = e instanceof TrackerNotLiveError;
      const delayMs = notLive ? 60_000 : Math.min(5_000 * 2 ** row.attempts, 5 * 60_000);
      d.store.markFailed(row.id, (e as Error).message, new Date(d.now().getTime() + delayMs).toISOString());
      if (notLive) {
        if (item.sync.status !== 'dry_run') d.commit([{ type: 'work_item.synced', workItemId: item.id, data: { status: 'dry_run', error: (e as Error).message } }]);
      } else {
        if (item.sync.status !== 'failed' || item.sync.lastError !== (e as Error).message) d.commit([{ type: 'work_item.synced', workItemId: item.id, data: { status: 'failed', error: (e as Error).message } }]);
        if (row.attempts >= 1) {
          d.alert({ kind: 'tracker_out_of_sync', severity: 'critical', workItemId: item.id, message: `${item.key ?? item.title}: ${row.op.replace('_', ' ')} to ${t.target} keeps failing (${(e as Error).message}). The tracker is out of sync until this is delivered.`, dedupeKey: `sync:${item.id}` });
        }
      }
      return false;
    }
  }
}

const STATE_FOR_NEW: Partial<Record<TrackerCategory, LifecycleState>> = { backlog: 'backlog', todo: 'selected', in_progress: 'selected', in_review: 'selected' };

export class TrackerPoller {
  readonly d: Daemon;
  private timer: NodeJS.Timeout | null = null;
  private busy = false;

  constructor(d: Daemon) {
    this.d = d;
  }

  start(): void {
    const c = this.d.config.tracker;
    const secs = c.type === 'local' ? 10 : c.poll_seconds;
    if (!this.timer) this.timer = setInterval(() => void this.poll(), secs * 1000);
    void this.poll();
  }

  stop(): void {
    if (this.timer) clearInterval(this.timer);
    this.timer = null;
  }

  async poll(): Promise<number> {
    if (this.busy || !this.d.tracker.live) return 0;
    this.busy = true;
    try {
      const since = this.d.store.kvGet('tracker:last_poll');
      const started = this.d.nowIso();
      const issues = await this.d.tracker.listIssues({ updatedSince: since });
      let n = 0;
      for (const i of issues) n += this.ingest(i) ? 1 : 0;
      this.d.store.kvSet('tracker:last_poll', since && since > started ? since : started);
      this.d.resolveAlerts((a) => a.dedupeKey === 'tracker-poll', 'polling works');
      return n;
    } catch (e) {
      this.d.alert({ kind: 'tracker_out_of_sync', severity: 'warn', message: `polling ${this.d.tracker.target} failed: ${(e as Error).message}`, dedupeKey: 'tracker-poll' });
      return 0;
    } finally {
      this.busy = false;
    }
  }

  /** Mirror one tracker issue. Returns true if anything changed. */
  ingest(i: TrackerIssue): boolean {
    const d = this.d;
    const existing = Object.values(d.state.workItems).find((w) => w.trackerId === i.id);
    if (!existing) {
      const state = STATE_FOR_NEW[i.status.category];
      if (!state) return false; // closed issues are history, not work
      const now = d.nowIso();
      const item: WorkItem = {
        id: newId('wi'),
        key: i.key,
        trackerId: i.id,
        url: i.url,
        title: i.title,
        description: i.description,
        acceptance: i.acceptance,
        labels: i.labels,
        priority: i.priority ?? 3,
        parentKey: i.parentKey,
        blockedBy: [],
        state,
        blockedOn: null,
        resumeTo: null,
        ownerAgentId: null,
        assignmentIds: [],
        runIds: [],
        branches: [],
        evidence: [],
        requiresProductionVerification: false,
        trackerStatus: i.status,
        sync: { status: 'synced', lastError: null, at: now },
        createdAt: now,
        updatedAt: now,
      };
      d.commit([{ type: 'work_item.created', actor: { type: 'human', id: `tracker:${d.tracker.type}` }, workItemId: item.id, data: { item } }]);
      if (i.status.category === 'in_progress') this.mismatch(item, `${i.key} is "${i.status.native}" in the tracker but has no live run here`);
      return true;
    }
    const patch: NonNullable<Extract<NewEvent, { type: 'work_item.updated' }>['data']>['patch'] = {};
    if (existing.title !== i.title) patch.title = i.title;
    if (existing.description !== i.description) patch.description = i.description;
    if (JSON.stringify(existing.acceptance) !== JSON.stringify(i.acceptance)) patch.acceptance = i.acceptance;
    if (JSON.stringify(existing.labels) !== JSON.stringify(i.labels)) patch.labels = i.labels;
    if (JSON.stringify(existing.trackerStatus) !== JSON.stringify(i.status)) patch.trackerStatus = i.status;
    if (Object.keys(patch).length === 0) return false;
    d.commit([{ type: 'work_item.updated', actor: { type: 'human', id: `tracker:${d.tracker.type}` }, workItemId: existing.id, data: { patch } }]);
    // Drift: the tracker says something our lifecycle (and pending writes) don't.
    const pending = d.store.pendingOutbox('9999').some((r) => r.workItemId === existing.id);
    const ours = DEFAULT_TRACKER_CATEGORY[existing.state];
    if (!pending && patch.trackerStatus && ours !== i.status.category) {
      if (i.status.category === 'done' && existing.state !== 'verified') this.mismatch(existing, `${i.key} was closed as done in the tracker, but Done here needs merge and acceptance evidence (state: ${existing.state})`);
      else if (i.status.category === 'canceled' && existing.state !== 'canceled') this.mismatch(existing, `${i.key} was canceled in the tracker; cancel it here too or reopen it there`);
      else this.mismatch(existing, `${i.key} is "${i.status.native}" in the tracker but "${existing.state}" here`);
    }
    return true;
  }

  private mismatch(item: WorkItem, message: string): void {
    this.d.alert({ kind: 'tracker_mismatch', severity: 'warn', workItemId: item.id, message, dedupeKey: `mismatch:${item.id}:${message}` });
  }
}

// SPDX-License-Identifier: Apache-2.0
// The daemon runs the project's required checks itself after an agent finishes, so "Done"
// rests on evidence the control center recorded, not on the agent's claims.
import fs from 'node:fs';
import path from 'node:path';
import { parseTestOutput, redact, type TestCounts } from '@acc/core';
import { runShell } from './exec.ts';

export interface CheckResult {
  name: string;
  command: string;
  exitCode: number | null;
  timedOut: boolean;
  counts: TestCounts | null;
  logPath: string;
  durationMs: number;
}

export async function runChecks(o: {
  cwd: string;
  checks: { name: string; command: string }[];
  logDir: string;
  env: NodeJS.ProcessEnv;
  denylist: string[];
  timeoutMs?: number;
}): Promise<CheckResult[]> {
  fs.mkdirSync(o.logDir, { recursive: true, mode: 0o700 });
  const results: CheckResult[] = [];
  for (const c of o.checks) {
    const t0 = Date.now();
    const r = await runShell(c.command, { cwd: o.cwd, env: { ...o.env, CI: '1', FORCE_COLOR: '0' }, timeoutMs: o.timeoutMs ?? 15 * 60_000 });
    const output = redact(`${r.stdout}\n${r.stderr}`, { denylist: o.denylist }).text;
    const logPath = path.join(o.logDir, `${c.name.replace(/[^\w.-]/g, '_')}.log`);
    fs.writeFileSync(logPath, `$ ${c.command}\n${output}\n[exit ${r.code ?? 'none'}${r.timedOut ? ', timed out' : ''}]\n`, { mode: 0o600 });
    results.push({ name: c.name, command: c.command, exitCode: r.code, timedOut: r.timedOut, counts: parseTestOutput(output), logPath, durationMs: Date.now() - t0 });
  }
  return results;
}

