export type WorkflowTaskStatus = 'pending' | 'queued' | 'running' | 'verifying' | 'done' | 'changes_requested' | 'blocked' | 'failed' | 'canceled';

export interface WorkflowTaskState {
  status: WorkflowTaskStatus;
