  id: string;
  title: string;
  owner: string;
  command: string;
  check: string;
  rollback: string;
  approval: 'not_required' | 'pending' | 'approved' | 'denied';
  status: 'todo' | 'running' | 'passed' | 'failed' | 'skipped';
}

export interface VaultStatus {
  root: string;
  folder: string;
  backend: 'fs' | 'obsidian-cli';
  cli: { available: boolean; path: string | null; note: string };
  notes: number;
  lastWriteAt: string | null;
  openUrl: string | null;
  error: string | null;
}

export interface GraphStatus {
  state: 'missing' | 'building' | 'ready' | 'error' | 'unavailable';
  sha: string | null;
  builtAt: string | null;
  nodes: number;
  edges: number;
  durationMs: number | null;
  graphPath: string | null;
  semantic: boolean;
  error: string | null;
}

