  };
  h.raw = formatHandoff(h);
  return h;
}

/** The daemon runs required checks itself and records the results as verified evidence. */
async postRunChecks(runId: string): Promise<void> {
  const d = this.d;
  const run = d.state.runs[runId];
  const asg = d.state.assignments[run.assignmentId];
  if (!asg.worktree || !fs.existsSync(asg.worktree)) return;
  const checks = asg.requiredChecks.map((name) => ({ name, command: d.config.project.checks[name] })).filter((c): c is { name: string; command: string } => Boolean(c.command));
  const refs = { agentId: run.agentId, workItemId: run.workItemId, assignmentId: run.assignmentId, runId };
  const sha = await headSha(asg.worktree);
  const results = checks.length ? await runChecks({ cwd: asg.worktree, checks, logDir: path.join(this.supervisor.runDir(runId), 'checks'), env: sanitizeEnv(d.state.agents[run.agentId].config, d.baseEnv()).env, denylist: d.denylist() }) : [];
  const events: NewEvent[] = [];
  let total = null as TestCounts | null;
  for (const r of results) {
    const passed = r.exitCode === 0;
    events.push({ type: 'work_item.evidence_added', ...refs, data: { evidence: this.evidence({ kind: r.counts ? 'test' : 'command', summary: `${r.name}: \`${r.command}\` → ${r.counts ? `${r.counts.passed} passed, ${r.counts.failed} failed` : passed ? 'ok' : 'failed'} (exit ${r.exitCode ?? 'none'}${r.timedOut ? ', timed out' : ''})`, command: r.command, exitCode: r.exitCode, counts: r.counts ?? undefined, sha: sha ?? undefined, branch: asg.branch ?? undefined, runId, logPath: r.logPath, env: 'local', verified: true }) } });
    if (r.counts) total = { passed: (total?.passed ?? 0) + r.counts.passed, failed: (total?.failed ?? 0) + r.counts.failed, skipped: (total?.skipped ?? 0) + r.counts.skipped, framework: r.counts.framework };
  }
  if (total) events.push({ type: 'run.tests', ...refs, data: { counts: total, command: results.filter((r) => r.counts).map((r) => r.command).join(' && '), source: 'daemon' } });
  const handoff = d.state.runs[runId].handoff;
  let outbox: { workItemId: string; op: 'comment'; payload: Record<string, unknown> }[] = [];
  if (handoff && handoff.source !== 'skeleton') {
    const verified = await this.verifyHandoff(handoff, runId, asg, results.map((r) => ({ command: r.command, exitCode: r.exitCode })));
    events.push({ type: 'run.handoff', ...refs, data: { handoff: verified } });
    const lines = [formatHandoff(verified), '', `**Verified by Agent Control Center**${sha ? ` at \`${sha.slice(0, 10)}\`` : ''}${asg.branch ? ` on \`${asg.branch}\`` : ''}:`];
    if (results.length === 0) lines.push('- no required checks configured');
    for (const r of results) lines.push(`- ${r.exitCode === 0 ? '✅' : '❌'} ${r.name}: \`${r.command}\` → ${r.counts ? `${r.counts.passed} passed, ${r.counts.failed} failed` : `exit ${r.exitCode ?? 'none'}`}`);
    outbox = [{ workItemId: run.workItemId, op: 'comment', payload: { body: lines.join('\n') } }];
  }
  d.commit(events, outbox);
  d.outbox.kick();
  const failed = results.filter((r) => r.exitCode !== 0);
  if (failed.length) {
    d.alert({ kind: 'run_failed', severity: 'warn', agentId: run.agentId, runId, workItemId: run.workItemId, message: `${d.state.workItems[run.workItemId].key}: required check${failed.length > 1 ? 's' : ''} ${failed.map((f) => f.name).join(', ')} failed after the handoff`, dedupeKey: `checks:${runId}` });
  }
}

// ---- control -----------------------------------------------------------------------------

async stop(runId: string, reason: string, actor: Actor = HUMAN, kind: 'stopped' | 'killed' = 'stopped', pause = false): Promise<void> {
  const run = this.d.state.runs[runId];
  if (!run) throw new CommandError(`unknown run ${runId}`, 404);
  if (!isActiveRun(run)) return;
  const ctx = this.getCtx(run);
  ctx.stopRequested = { reason, kind, pause };

export interface IssueInput { title: string; description?: string; acceptance?: string[]; labels?: string[]; priority?: number; requiresProductionVerification?: boolean; parentKey?: string | null }

export interface AssignmentInput {
  workItemId: string;
  agentId: string;
  allowedPaths?: string[];
  scope?: string;
  requiredChecks?: string[];
  askHumanIf?: string[];
  model?: string | null;
  /** Commit or branch the worktree starts from (default: the integration branch). */
  baseRef?: string;
  kind?: Assignment['kind'];
  review?: Assignment['review'];
  workflowId?: string | null;
  taskId?: string | null;
}

export class CommandError extends Error {
  status: number;

createAssignment(input: AssignmentInput, actor: Actor = HUMAN): Assignment {
  const item = this.state.workItems[input.workItemId];
  if (!item) throw new CommandError(`unknown work item ${input.workItemId}`, 404);
  const agent = this.state.agents[input.agentId];
  if (!agent) throw new CommandError(`unknown agent ${input.agentId}`, 404);
  const relay = agent.config.adapter === 'relay';
  const requiredChecks = input.requiredChecks ?? this.config.project.required_checks ?? Object.keys(this.config.project.checks);
  const a: Assignment = {
    id: newId('as'),
    workItemId: item.id,
    agentId: agent.id,
    position: 'draft',
    scope: input.scope ?? '',
    allowedPaths: input.allowedPaths ?? [],
    worktree: null,
    branch: null,
    baseRef: input.baseRef ?? this.config.project.integration_branch,
    baseSha: null,
    requiredChecks,
    askHumanIf: input.askHumanIf ?? DEFAULT_ASK_HUMAN_IF,
    handoffFormat: HANDOFF_TEMPLATE,
    designRevision:this.state.design?.hash??null,
    prompt: '',
    promptEdited: false,
    model: input.model ?? null,
    effort: agent.config.effort ?? null,
    preflight: null,
    createdAt: this.nowIso(),
    dispatchedAt: null,
    ...(input.kind ? { kind: input.kind } : {}),
    ...(input.review ? { review: input.review } : {}),
    ...(input.workflowId ? { workflowId: input.workflowId, taskId: input.taskId ?? null } : {}),
  };
  a.prompt = this.assignmentText(a, relay);
  this.commit([{ type: 'assignment.created', actor, agentId: a.agentId, workItemId: a.workItemId, assignmentId: a.id, data: { assignment: a } }]);
  return this.state.assignments[a.id];
}

