    const [k, ...v] = part.trim().split('=');
    if (k === name) return decodeURIComponent(v.join('='));
  }
  return null;
}

export interface ServerOptions {
  port: number;
  host?: string;
  /** Extra allowed Origins (Vite dev server). */
  devOrigins?: string[];
}

