emit.edit('e1', file);
if (scenario === 'break-tests') {
  fs.writeFileSync(path.join(cwd, `notes/${key}.test.mjs`), "import test from 'node:test';\ntest('broken on purpose', () => { throw new Error('broken'); });\n");
  emit.edit('e2', `notes/${key}.test.mjs`);
}

