if (vendor === 'codex' && args[0] === 'login' && args[1] === 'status') {
  console.error(process.env.FAKE_LOGGED_OUT === '1' ? 'Not logged in' : process.env.FAKE_AUTH_METHOD === 'api' ? 'Logged in using an API key - sk-***' : 'Logged in using ChatGPT');
