      ev('t.message', { role: 'assistant', text: 'Working on it' }, { runId: 'r1' }),
      ev('t.command', { command: 'npm test', status: 'failed', exitCode: 1, output: 'boom' }, { runId: 'r1' }),
      ev('t.file_edit', { path: 'src/a.ts', change: 'modify' }, { runId: 'r1' }),
