    expect(wf(h, saved.id).tasks.second).toMatchObject({ status: 'pending', assignmentId: null });

    h = await restart(h, cfg, env);
    expect(wf(h, saved.id)).toMatchObject({ status: 'paused', tasks: { first: { status: 'done' }, second: { status: 'pending' } } });
