    const ok = await save({ name: 'ok', mode: 'collaborative', tasks: [t('x', { allowedPaths: ['notes/**'] }), { id: 'rx', kind: 'review', reviewOf: 'x', agentId: 'codex' }, t('y', { workItemId: b.id, agentId: 'cursor', allowedPaths: ['notes/**'], dependsOn: ['rx'] })] });
